{"code":"function reconcile(events) {
  var RANK = { queued: 0, sent: 1, failed: 2, delivered: 3, read: 4 };
  var out = [];
  if (!Array.isArray(events)) return out;
  var byCompany = new Map();
  for (var i = 0; i < events.length; i++) {
    var e = events[i];
    if (e === null || typeof e !== 'object' || Array.isArray(e)) continue;
    var company = e.company;
    var id = e.id;
    var status = e.status;
    var at = e.at;
    if (typeof company !== 'string' || company.length === 0) continue;
    if (typeof id !== 'string' || id.length === 0) continue;
    if (typeof status !== 'string') continue;
    if (!Object.prototype.hasOwnProperty.call(RANK, status)) continue;
    if (typeof at !== 'number' || !Number.isInteger(at) || at < 0) continue;
    var ids = byCompany.get(company);
    if (ids === undefined) {
      ids = new Map();
      byCompany.set(company, ids);
    }
    var cur = ids.get(id);
    if (cur === undefined) {
      ids.set(id, { company: company, id: id, status: status, at: at });
      continue;
    }
    var curRank = RANK[cur.status];
    var newRank = RANK[status];
    if (newRank > curRank) {
      cur.status = status;
      cur.at = at;
    } else if (newRank === curRank && at > cur.at) {
      cur.at = at;
    }
  }
  var companies = [];
  byCompany.forEach(function (v, k) { companies.push(k); });
  companies.sort(function (a, b) { return a < b ? -1 : a > b ? 1 : 0; });
  for (var c = 0; c < companies.length; c++) {
    var map = byCompany.get(companies[c]);
    var keys = [];
    map.forEach(function (v, k) { keys.push(k); });
    keys.sort(function (a, b) { return a < b ? -1 : a > b ? 1 : 0; });
    for (var j = 0; j < keys.length; j++) {
      var r = map.get(keys[j]);
      out.push({ company: r.company, id: r.id, status: r.status, at: r.at });
    }
  }
  return out;
}"}

